import java.io.*;
import java.util.*;

class FenwickTree {
    long[] val;

    FenwickTree(int n) {
        val = new long[n + 1];
    }

    void add(int x, long v) {
        int n = val.length;
        while (x < n) {
            val[x] += v;
            x += x & (-x);
        }
    }

    long sum(int x) {
        if (x >= val.length) throw new AssertionError();
        long ans = 0;
        while (x > 0) {
            ans += val[x];
            x -= x & (-x);
        }
        return ans;
    }
}

class PrimeCountSolver {
    ArrayList<Long> query;
    ArrayList<Long> memo;

    PrimeCountSolver() {
        query = new ArrayList<>();
        memo = new ArrayList<>();
    }

    void add(long n) {
        query.add(n);
    }

    static ArrayList<Long> sieve(int n) {
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        for (int i = 2; ; i++) {
            if ((long) i * i > n) break;
            if (isPrime[i]) {
                int j = i * i;
                while (j <= n) {
                    isPrime[j] = false;
                    j += i;
                }
            }
        }
        ArrayList<Long> prime = new ArrayList<>();
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) prime.add((long) i);
        }
        return prime;
    }

    void build() {
        Collections.sort(query);
        ArrayList<Long> dedupQuery = new ArrayList<>();
        Long prev = null;
        for (Long v : query) {
            if (!v.equals(prev)) {
                dedupQuery.add(v);
                prev = v;
            }
        }
        query = dedupQuery;

        long n = query.isEmpty() ? 1 : query.get(query.size() - 1);
        long m = 1;
        while ((m + 1) * (m + 1) <= n) {
            m += 1;
        }
        ArrayList<Long> p = sieve((int) m);
        long bound = (long) Math.pow(Math.cbrt(n), 2) + 2;

        ArrayList<long[]> stack = new ArrayList<>();
        for (long v : query) {
            int k = binarySearchPrimeSquare(p, v);
            stack.add(new long[]{v, k});
        }

        ArrayList<long[]> smallQuery = new ArrayList<>();
        while (!stack.isEmpty()) {
            long[] cur = stack.remove(stack.size() - 1);
            long nn = cur[0];
            int k = (int) cur[1];
            if (k == 0) continue;
            long q = p.get(k - 1);
            if (q * q > nn) {
                int x = binarySearchPrimeSquarePrefix(p, k, nn);
                stack.add(new long[]{nn, x});
            } else if (nn <= bound) {
                smallQuery.add(new long[]{k, nn});
            } else {
                stack.add(new long[]{nn, k - 1});
                stack.add(new long[]{nn / q, k - 1});
            }
        }

        smallQuery.sort(Comparator.comparingLong(a -> a[0] * (bound + 1) + a[1]));
        ArrayList<long[]> dedupSmallQuery = new ArrayList<>();
        long[] prevArr = null;
        for (long[] v : smallQuery) {
            if (prevArr == null || prevArr[0] != v[0] || prevArr[1] != v[1]) {
                dedupSmallQuery.add(v);
                prevArr = v;
            }
        }
        smallQuery = dedupSmallQuery;

        int mm = (int) bound;
        FenwickTree bit = new FenwickTree(mm);
        for (int i = 1; i <= mm; i++) {
            bit.add(i, 1);
        }
        boolean[] isPrime = new boolean[mm + 1];
        Arrays.fill(isPrime, true);
        long[] memoSmall = new long[smallQuery.size()];
        int pos = 0;
        for (int i = 0; i < p.size(); i++) {
            int prime = p.get(i).intValue();
            int j = prime;
            while (j <= mm) {
                if (isPrime[j]) {
                    bit.add(j, -1);
                }
                isPrime[j] = false;
                j += prime;
            }
            while (pos < smallQuery.size()) {
                long[] qv = smallQuery.get(pos);
                int k = (int) qv[0];
                long nn = qv[1];
                if (k > i + 1) break;
                memoSmall[pos] = bit.sum((int) nn);
                pos++;
            }
            if (pos >= smallQuery.size()) break;
        }

        memo.clear();
        for (int i = 0; i < query.size(); i++) memo.add(0L);

        ArrayList<long[]> stack2 = new ArrayList<>();
        for (int i = 0; i < query.size(); i++) {
            long nn = query.get(i);
            int k = binarySearchPrimeSquare(p, nn);
            memo.set(i, memo.get(i) + (long) k - 1);
            stack2.add(new long[]{nn, k, 1, i});
        }

        while (!stack2.isEmpty()) {
            long[] cur = stack2.remove(stack2.size() - 1);
            long nn = cur[0];
            int k = (int) cur[1];
            long sign = cur[2];
            int idx = (int) cur[3];
            if (k == 0) {
                memo.set(idx, memo.get(idx) + sign * nn);
                continue;
            }
            long q = p.get(k - 1);
            if (q * q > nn) {
                int x = binarySearchPrimeSquarePrefix(p, k, nn);
                memo.set(idx, memo.get(idx) - sign * (k - x));
                stack2.add(new long[]{nn, x, sign, idx});
            } else if (nn <= bound) {
                int posIdx = binarySearchSmallQuery(smallQuery, k, nn);
                memo.set(idx, memo.get(idx) + sign * memoSmall[posIdx]);
            } else {
                stack2.add(new long[]{nn, k - 1, sign, idx});
                stack2.add(new long[]{nn / q, k - 1, -sign, idx});
            }
        }
    }

    long get(long n) {
        int idx = Collections.binarySearch(query, n);
        return memo.get(idx);
    }

    private static int binarySearchPrimeSquare(ArrayList<Long> p, long v) {
        int lo = 0, hi = p.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long val = p.get(mid);
            long sq = val * val;
            if (sq == v) return mid + 1;
            if (sq < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private static int binarySearchPrimeSquarePrefix(ArrayList<Long> p, int k, long v) {
        int lo = 0, hi = k;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long val = p.get(mid);
            long sq = val * val;
            if (sq == v) return mid + 1;
            if (sq < v) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    private static int binarySearchSmallQuery(ArrayList<long[]> arr, int k, long n) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long[] v = arr.get(mid);
            if (v[0] == k && v[1] == n) return mid;
            if (v[0] < k || (v[0] == k && v[1] < n)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

public class Main {
    static ArrayList<Long> sieve(int n) {
        return PrimeCountSolver.sieve(n);
    }

    static void run() throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String s = br.readLine();
        long n = Long.parseLong(s.trim());
        ArrayList<Long> p = sieve((int) (Math.sqrt(n)) + 2);
        long ans = 0;
        for (long prime : p) {
            if (prime * prime * prime <= n) {
                ans += 1;
            } else {
                break;
            }
        }
        PrimeCountSolver solver = new PrimeCountSolver();
        for (int i = 0; i < p.size(); i++) {
            long prime = p.get(i);
            if (prime * prime <= n) {
                ans -= i + 1;
                solver.add(n / prime);
            }
        }
        solver.build();
        for (long prime : p) {
            if (prime * prime <= n) {
                ans += solver.get(n / prime);
            }
        }
        System.out.println(ans);
    }

    public static void main(String[] args) throws Exception {
        run();
    }
}

