            long[] top = stack.remove(stack.size() - 1);
            long nn = top[0];
            int k = (int) top[1];
            if (k == 0) {
                continue;
            }
            long q = p.get(k - 1);
            if (q * q > nn) {
                int x = binarySearchBySquare(p, nn, k);
