        queryPairs.sort((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            return Long.compare(a[1], b[1]);
        });
        ArrayList<long[]> dedupQueryPairs = new ArrayList<>();
        long[] prevPair = null;
        for (long[] v : queryPairs) {
