        int lo = 0, hi = p.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long val = p.get(mid);
            long sq = val * val;
            if (sq == v) {
                return mid + 1;
            } else if (sq < v) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int binarySearchBySquare(ArrayList<Long> p, long v, int hiLimit) {
        int lo = 0, hi = hiLimit;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long val = p.get(mid);
            long sq = val * val;
            if (sq == v) {
                return mid + 1;
            } else if (sq < v) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

