class PrimeCountSolver {
    List<Long> query;
    List<Long> memo;

    PrimeCountSolver() {
        query = new ArrayList<>();
        memo = new ArrayList<>();
    }

    static List<Long> sieve(int n) {
        boolean[] isPrime = new boolean[n + 1];
        Arrays.fill(isPrime, true);
        for (int i = 2; ; i++) {
            if ((long) i * i > n) {
                break;
            }
            if (isPrime[i]) {
                int j = i * i;
                while (j <= n) {
                    isPrime[j] = false;
                    j += i;
                }
            }
        }
        int len = 0;
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) len++;
        }
        List<Long> prime = new ArrayList<>(len);
        for (int i = 2; i <= n; i++) {
            if (isPrime[i]) {
                prime.add((long) i);
            }
        }
        return prime;
    }

    void add(long n) {
        query.add(n);
    }

    void build() {
        Collections.sort(query);
        List<Long> dedupQuery = new ArrayList<>();
        Long prev = null;
        for (Long v : query) {
            if (!v.equals(prev)) {
                dedupQuery.add(v);
                prev = v;
            }
        }
        query = dedupQuery;
        long n = query.isEmpty() ? 1 : query.get(query.size() - 1);
        long m = 1;
        while ((m + 1) * (m + 1) <= n) {
            m += 1;
        }
        List<Long> p = sieve((int) m);
        long bound = (long) Math.pow(Math.cbrt(n), 2) + 2;
        List<long[]> stack = new ArrayList<>();
        for (long v : query) {
            int k = binarySearchBySquare(p, v);
            stack.add(new long[]{v, k});
        }
        List<long[]> smallQuery = new ArrayList<>();
        while (!stack.isEmpty()) {
            long[] cur = stack.remove(stack.size() - 1);
            long nn = cur[0];
            int k = (int) cur[1];
            if (k == 0) {
                continue;
            }
            long q = p.get(k - 1);
            if (q * q > nn) {
                int x = binarySearchBySquare(p.subList(0, k), nn);
                stack.add(new long[]{nn, x});
            } else if (nn <= bound) {
                smallQuery.add(new long[]{k, nn});
            } else {
                stack.add(new long[]{nn, k - 1});
                stack.add(new long[]{nn / q, k - 1});
            }
        }
        smallQuery.sort(Comparator.comparingLong(a -> a[0] * (bound + 1) + a[1]));
        List<long[]> dedupSmallQuery = new ArrayList<>();
        long[] prevQ = null;
        for (long[] qv : smallQuery) {
            if (prevQ == null || qv[0] != prevQ[0] || qv[1] != prevQ[1]) {
                dedupSmallQuery.add(qv);
                prevQ = qv;
            }
        }
        smallQuery = dedupSmallQuery;
        int mm = (int) bound;
        FenwickTree bit = new FenwickTree(mm);
        for (int i = 1; i <= mm; i++) {
            bit.add(i, 1);
        }
        boolean[] isPrime = new boolean[mm + 1];
        Arrays.fill(isPrime, true);
        long[] memoArr = new long[smallQuery.size()];
        int pos = 0;
        for (int i = 0; i < p.size(); i++) {
            int prime = p.get(i).intValue();
            int j = prime;
            while (j <= mm) {
                if (isPrime[j]) {
                    bit.add(j, -1);
                }
                isPrime[j] = false;
                j += prime;
            }
            while (pos < smallQuery.size()) {
                long[] qv = smallQuery.get(pos);
                int k = (int) qv[0];
                long nn = qv[1];
                if (k > i + 1) {
                    break;
                } else {
                    memoArr[pos] = bit.sum((int) nn);
                    pos++;
                }
            }
            if (pos >= smallQuery.size()) {
                break;
            }
        }
        memo.clear();
        for (int i = 0; i < query.size(); i++) {
            memo.add(0L);
        }
        stack.clear();
        for (int i = 0; i < query.size(); i++) {
            long nn = query.get(i);
            int k = binarySearchBySquare(p, nn);
            memo.set(i, memo.get(i) + (long) k - 1);
            stack.add(new long[]{nn, k, 1, i});
        }
        while (!stack.isEmpty()) {
            long[] cur = stack.remove(stack.size() - 1);
            long nn = cur[0];
            int k = (int) cur[1];
            long sign = cur[2];
            int idx = (int) cur[3];
            if (k == 0) {
                memo.set(idx, memo.get(idx) + sign * nn);
                continue;
            }
            long q = p.get(k - 1);
            if (q * q > nn) {
                int x = binarySearchBySquare(p.subList(0, k), nn);
                memo.set(idx, memo.get(idx) - sign * (k - x));
                stack.add(new long[]{nn, x, sign, idx});
            } else if (nn <= bound) {
                int posQ = binarySearchPair(smallQuery, k, nn);
                memo.set(idx, memo.get(idx) + sign * memoArr[posQ]);
            } else {
                stack.add(new long[]{nn, k - 1, sign, idx});
                stack.add(new long[]{nn / q, k - 1, -sign, idx});
            }
        }
    }

    long get(long n) {
        int idx = Collections.binarySearch(query, n);
        return memo.get(idx);
    }

    private static int binarySearchBySquare(List<Long> p, long v) {
        int lo = 0, hi = p.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long pm = p.get(mid);
            long sq = pm * pm;
            if (sq == v) {
                return mid + 1;
            } else if (sq < v) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }

    private static int binarySearchPair(List<long[]> arr, int k, long n) {
        int lo = 0, hi = arr.size();
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            long[] v = arr.get(mid);
            if (v[0] == k) {
                if (v[1] < n) {
                    lo = mid + 1;
                } else if (v[1] > n) {
                    hi = mid;
                } else {
                    return mid;
                }
            } else if (v[0] < k) {
                lo = mid + 1;
            } else {
                hi = mid;
            }
        }
        return lo;
    }
}

